const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>n===null||n===undefined?'—':Number(n).toLocaleString('zh-CN',{maximumFractionDigits:4});
const statusNames={confirmed:'已核算',pending:'待审核',duplicate:'重复申报',outside:'范围外',excluded:'人工排除'};
const tag=r=>`<span class="tag ${esc(r.status)}">${statusNames[r.status]||esc(r.status)}</span>`;
const names={projects:'项目管理',college:'本学院名册',overview:'工作概览',students:'学生汇总',records:'申报明细',review:'待审核',duplicates:'重复核对',registry:'基础信息维护',rules:'计分规则',archives:'历史归档'};
let data,token='',archiveId='',actor=localStorage.getItem('assessment-actor')||'',page='overview',filter={q:'',category:'',status:'',className:''},pageNo=1;
let pendingFiles=[],previewReports=[],toastTimer;
let registryTab='students',projectId=sessionStorage.getItem('assessment-project')||'legacy',projectList=[],collegeRegistry=null;
let registryFilters={department:'',classId:'',active:''},registrySelected=new Set();
const registryMaster=()=>page==='college'?collegeRegistry:data.registry;
const registryLocked=()=>page==='college'?false:locked();
const registryEndpoint=()=>page==='college'?'/api/college-registry':'/api/registry';
let studentContext=null;
let duplicatePrompt=null,duplicateScope='open';
const dialog=$('#dialog');
const locked=()=>data?.locked||!!archiveId;
function toast(message,error=false){const e=$('#toast');e.textContent=message;e.className=`show${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.className='',4200)}
async function api(path,body){const headers={'X-Project-Id':projectId||'legacy'};if(body!==undefined)Object.assign(headers,{'Content-Type':'application/json','X-Assessment-Token':token});const res=await fetch(path,{headers,...(body===undefined?{}:{method:'POST',body:JSON.stringify(body)})});const value=await res.json();if(!res.ok)throw new Error(value.error||'操作失败');return value}
async function reload(){const catalog=await api('/api/projects');projectList=catalog.projects;token=catalog.token;collegeRegistry=await api('/api/college-registry');if(!projectList.some(p=>p.id===projectId&&!p.deleted))projectId=projectList.find(p=>!p.deleted)?.id||'';sessionStorage.setItem('assessment-project',projectId);if(projectId){data=await api('/api/state');token=data.token}else{data={college:'全部学院',year:'',registry:{departments:[],classes:[],students:[]},stats:{pending:0},duplicate_groups:[],locked:false};location.hash='projects'}archiveId='';render()}

function heading(title,subtitle,buttons='',eyebrow=data.year+' / UNDERGRADUATE'){return `<div class="page-heading"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${buttons}</div></div>`}
function button(label,action,secondary=false,disabled=false,attrs=''){return `<button class="btn${secondary?' secondary':''}" data-action="${action}" ${disabled?'disabled':''} ${attrs}>${label}</button>`}
function exportLink(mode,label){return `<a class="btn secondary" href="/api/export?mode=${mode}${archiveId?'&archive='+archiveId:''}">${label}</a>`}
function empty(title,description){return `<div class="empty"><div class="empty-icon">▤</div><strong>${esc(title)}</strong>${esc(description)}</div>`}
function stat(label,value,unit,note,symbol,amber=false){return `<div class="stat${amber?' amber':''}"><div class="stat-top">${label}<span class="stat-symbol">${symbol}</span></div><div class="stat-value">${num(value)}<small>${unit}</small></div><div class="stat-note">${note}</div></div>`}
function overview(){
 const s=data.stats,den=s.records-s.outside,percent=den?Math.round((den-s.pending)/den*100):0;
 const cats=data.categories.map(c=>({name:c,n:data.records.filter(r=>!r.scope_reason&&r.category===c).length})).filter(c=>c.n).sort((a,b)=>b.n-a.n).slice(0,5),max=Math.max(1,...cats.map(c=>c.n));
 return heading('综合测评工作台',`${esc(data.college)} · 本科生附加分核算与审核`,button('＋ 导入工作簿','import',false,locked())+exportLink('summary','↓ 导出汇总'))+
 `<section class="hero"><div><p class="eyebrow">${locked()?'ARCHIVED · 历史留存':'WORK IN PROGRESS · 临时库'}</p><h2>${locked()?'本版已归档，结果已锁定。':'每一分有依据，每一步可追溯。'}</h2><p>${locked()?'历史版本保留原始申报、核算结果与审核记录。需要更正时，请创建修订版。':'从工作簿导入申报，按规则计算并审核差异。确认后转入历史库长期保存。'}</p></div><div class="hero-right">${button(locked()?'查看历史归档 ↗':'进入待审核 →',locked()?'archives':'review')}<small>${locked()?'归档版本只读':'当前 '+num(s.pending)+' 条记录需要确认'}</small></div></section>`+
 `<div class="cards">${stat('测评学生',s.students,'人','当前学院 · 已识别本科生','▦')}${stat('导入申报',s.records,'条',data.files.length+' 个工作簿 · 保留原始出处','≡')}${stat('待审核',s.pending,'条','分值差异、身份与特殊项目','⌁',true)}<a href="#duplicates" class="stat-link">${stat('重复核对',(data.duplicate_groups||[]).length,'组',s.duplicates+' 条完全重复去重 · 查看全部来源 ↗','⧉')}</a></div>`+
 `<div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>本期审核进度</h2><p>临时库里的结果，确认后才会归档</p></div><span class="tag ${s.pending?'pending':''}">${locked()?'已锁定':s.pending?'审核中':'可归档'}</span></div><div class="panel-body"><div class="flow"><div class="flow-step"><span class="step-circle">1</span><strong>导入临时库</strong><p>识别类别与学生信息<br>保留原分值与来源</p></div><div class="flow-step"><span class="step-circle">2</span><strong>核算与审核</strong><p>核对差异和重复项目<br>填写确认依据</p></div><div class="flow-step"><span class="step-circle">3</span><strong>确认归档</strong><p>保存当时的全部结果<br>锁定历史版本</p></div></div><div class="progress-line"><span>当前范围内已处理 ${num(den-s.pending)} / ${num(den)} 条</span><strong>${percent}%</strong></div><div class="progress"><span style="width:${percent}%"></span></div><div class="notice">${s.pending?`待审核记录暂不计入汇总。当前分数为试算结果。 <a href="#review">去核对 →</a>`:`${s.outside?num(s.outside)+' 条范围外记录不计入本期。':''} <a href="#archives">查看归档条件 →</a>`}</div></div></section><section class="panel"><div class="panel-head"><div><h2>申报类别分布</h2><p>当前学院范围 · 按申报条数统计</p></div><a href="#records" class="link-button">全部明细 ↗</a></div><div class="panel-body">${cats.length?cats.map(c=>`<div class="category-row"><span class="category-name">${esc(c.name)}</span><span class="category-bar"><i style="width:${c.n/max*100}%"></i></span><strong>${num(c.n)}</strong><small>条</small></div>`).join(''):empty('暂无申报','导入工作簿开始核算')}</div><div class="boundary-note">奖励和处罚分别封顶 10 分；研究生记录不适用本套本科生办法。</div></section></div>`+
 `<section class="panel"><div class="panel-head"><div><h2>已导入的工作簿</h2><p>原表只读，调整与审核发生在临时库</p></div><span class="muted" style="font-size:11px">${data.files.length} 个文件</span></div><div class="table-wrap"><table><thead><tr><th>来源文件</th><th>有效申报</th><th>工作表</th><th>导入状态</th></tr></thead><tbody>${data.files.map(f=>`<tr><td><div class="file-cell"><span class="source-icon">XLSX</span><div class="file-name">${esc(f.name)}<small>${esc(f.imported_at?.replace('T',' ').slice(0,16)||'本机数据')}</small></div></div></td><td>${num(f.count)} 条</td><td>${f.sheets.filter(s=>s.count).length} 张</td><td><span class="tag">${f.count?'已载入':'空白模板'}</span></td></tr>`).join('')}</tbody></table></div>${!data.files.length?empty('还没有工作簿','点击右上角导入，可同时选择多个文件'):''}</section>`;
}
function filtersHTML(type){
 const classes=[...new Set(data.students.map(s=>s.class_name))].filter(Boolean).sort();
 return `<div class="toolbar"><div class="search"><input id="search-input" aria-label="搜索" placeholder="${type==='students'?'搜索姓名、学号、班级':'搜索姓名、学号、项目或文件'}" value="${esc(filter.q)}"></div><div class="filters">${type==='students'?`<select id="class-filter" aria-label="班级"><option value="">全部班级</option>${classes.map(c=>`<option ${filter.className===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`:`<select id="category-filter" aria-label="附加分类别"><option value="">全部类别</option>${data.categories.map(c=>`<option ${filter.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`}${type==='students'?`<select id="category-filter" aria-label="附加分类别"><option value="">全部类别</option>${data.categories.map(c=>`<option ${filter.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`:''}${type!=='review'?`<select id="status-filter" aria-label="状态"><option value="">全部状态</option>${(type==='students'?[['pending','有待审核'],['complete','已核算']]:Object.entries(statusNames)).map(([k,v])=>`<option value="${k}" ${filter.status===k?'selected':''}>${v}</option>`).join('')}</select>`:''}</div></div>`;
}
function pagination(total){const pages=Math.max(1,Math.ceil(total/40));pageNo=Math.min(pageNo,pages);return `<div class="pagination"><span>共 ${num(total)} 条 · 每页 40 条</span><div class="actions">${button('上一页','prev',true,pageNo<=1)}<span>${pageNo} / ${pages}</span>${button('下一页','next',true,pageNo>=pages)}</div></div>`}
function students(){
 const q=filter.q.toLowerCase(),cat=filter.category,byStudent=new Map();
 if(cat)for(const r of data.records){if(!r.scope_reason&&r.effective_category===cat){if(!byStudent.has(r.student_key))byStudent.set(r.student_key,[]);byStudent.get(r.student_key).push(r)}}
 const rows=data.students.map(s=>{const selected=cat?(byStudent.get(s.key)||[]):null;return {...s,shownCount:selected?selected.length:s.count,shownPending:selected?selected.filter(r=>r.status==='pending').length:s.pending,categoryScore:cat?(s.categories[cat]||0):null}})
 .filter(s=>(s.name+s.student_id+s.classes.join(' ')).toLowerCase().includes(q)&&(!filter.className||s.class_name===filter.className)&&(!cat||s.shownCount>0)&&(!filter.status||(filter.status==='pending'?s.shownPending:!s.shownPending)));
 if(cat)rows.sort((a,b)=>b.categoryScore-a.categoryScore||a.student_id.localeCompare(b.student_id));
 const pager=pagination(rows.length),slice=rows.slice((pageNo-1)*40,pageNo*40);
 return heading('学生汇总','按学号归集附加分。选择类别可单独查看该类分值，点击学生查看计算过程。',exportLink('summary','↓ 导出全部类别汇总'))+
 `<section class="panel">${filtersHTML('students')}<div class="table-summary">当前：${esc(data.college)}本科生 · ${num(rows.length)} 人 · ${cat?'筛选 '+esc(cat)+'，按本类分值排序；总附加分仍包含所有类别。':'按已确认附加分排序，非正式综测名次。'}</div><div class="table-wrap"><table><thead><tr><th>学生</th><th>班级（原表/名册）</th><th>${cat?'本类申报':'申报'}</th>${cat?'<th>本类分值</th>':'<th>奖励分</th><th>处罚分</th>'}<th>${cat?'总附加分':'附加分'}</th><th>综测总分</th><th>${cat?'本类状态':'核算状态'}</th><th></th></tr></thead><tbody>${slice.map(s=>`<tr class="click-row" data-student="${esc(s.key)}"><td><div class="student-cell"><span class="student-avatar">${esc(s.name.slice(-2))}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.student_id)}</small></span></div></td><td>${esc(s.class_name)}${s.classes.length>1?`<small style="display:block">${s.classes.length} 种班级写法</small>`:''}</td><td>${s.shownCount} 条</td>${cat?`<td class="amount large">${num(s.categoryScore)}</td>`:`<td>${num(s.reward)}</td><td>${num(s.penalty)}</td>`}<td class="amount large">${num(s.net)}</td><td>${s.total===null?'<span class="dash">未填基础分</span>':num(s.total)}</td><td><span class="tag ${s.shownPending?'pending':''}">${s.shownPending?s.shownPending+' 条待审核':locked()?'已归档':'已核算'}</span>${cat&&s.pending>s.shownPending?'<small style="display:block">其他类别仍待审核</small>':''}</td><td><button class="link-button" data-student="${esc(s.key)}" aria-label="查看${esc(s.name)}详情">查看 ↗</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('没有匹配的学生','调整筛选条件，或导入该学院的申报表'):''}${pager}</section>`;
}
function records(review=false){
 const q=filter.q.toLowerCase();const rows=data.records.filter(r=>(!review||r.status==='pending')&&(!filter.category||r.category===filter.category)&&(!filter.status||r.status===filter.status)&&(r.name+r.student_id+r.event+r.source+r.award).toLowerCase().includes(q));
 const pager=pagination(rows.length),slice=rows.slice((pageNo-1)*40,pageNo*40);
 return heading(review?'待审核记录':'申报明细',review?'保留原表分值，核对规则建议，再确认计分方式。':'每条申报均可追溯到原始文件、工作表和行号。',review?button('查看计分规则 ↗','rules',true):button('＋ 新增申报','manual',false,locked())+exportLink('details','↓ 导出明细'))+
 (review?`<div class="review-banner"><div><strong>${num(data.stats.pending)} 条记录等待确认</strong><p>待审核记录暂不计分；完全重复申报自动不重复计分。所有更正与审核都会留下记录。</p></div><span class="tag pending">临时库</span></div>`:'')+
 `<section class="panel">${filtersHTML(review?'review':'records')}<div class="table-summary">${review?'可选择原表分值、规则分值、手动分值或排除本条。':'范围外记录保留备查，不参与当前学院本科生汇总。'}</div><div class="table-wrap"><table><thead><tr><th>学生</th><th>申报项目</th><th>类别</th><th>原表 / 规则</th><th>${review?'待确认原因':'状态'}</th><th>计入</th><th></th></tr></thead><tbody>${slice.map(r=>`<tr><td><div class="student-cell"><span><strong>${esc(r.name||'未填写姓名')}</strong><small>${esc(r.student_id||'缺少学号')}</small></span></div></td><td class="event-cell"><strong>${esc(r.event||'未填写项目')}</strong><small title="${esc(r.award)}">${esc(r.award)} · ${esc(r.level)} · ${esc(r.kind)}</small></td><td><small>${esc(r.category)}</small></td><td>${num(r.original_score)} <span class="dash">/</span> ${num(r.suggested)}</td><td>${review?`<div class="issue-text">${r.issues.map(esc).join('<br>')}</div>`:tag(r)}</td><td class="amount">${num(r.credited)}</td><td><button class="btn small secondary" data-record="${esc(r.id)}">${locked()?'查看':review?'审核':'详情'}</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty(review?'当前没有待审核记录':'没有匹配的申报',review?'可前往历史归档确认保存本版结果。':'试试更换关键词或类别。'):''}${pager}</section>`;
}
function duplicateComparison(group,compact=false){
 const members=group.member_ids.map(id=>data.records.find(r=>r.id===id)).filter(Boolean);
 return `<div class="table-wrap"><table class="duplicate-table"><thead><tr><th>本组处理</th><th>来源文件 / 工作表 / 行号</th><th>奖项与属性</th><th>原表分值</th><th>本次计入</th><th></th></tr></thead><tbody>${members.map(r=>`<tr class="${r.id===group.keeper_id?'kept-row':''}"><td><span class="tag ${r.id===group.keeper_id?'':'duplicate'}">${esc(r.duplicate_disposition||(r.id===group.keeper_id?'保留参与核算':'不重复计入'))}</span><small style="display:block;margin-top:5px">${esc(r.id===group.keeper_id?statusNames[r.status]:group.match_type||'完全重复')}</small></td><td class="source-detail"><strong>${esc(r.source)}</strong><small>${esc(r.sheet)} · 第 ${r.row} 行</small>${r.event_date?`<small>项目时间：${esc(r.event_date)}</small>`:''}</td><td>${esc(r.award)}<small style="display:block">${esc(r.level)} · ${esc(r.kind)}</small></td><td>${num(r.original_score)}</td><td class="amount">${num(r.credited)}<small style="display:block;font-weight:400">${r.status==='pending'?'待审核':r.id===group.keeper_id?(r.credited===0?'受归并/上限影响':'已进入分类核算'):esc(group.match_type||'已去重')}</small></td><td><button class="btn small secondary" data-record="${esc(r.id)}">${locked()?'查看':'查看 / 审核'}</button></td></tr>`).join('')}</tbody></table></div>${compact?'':'<div class="boundary-note">保留项仍受同项目取最高、分类封顶及待审核状态影响，并不一定实际加分。</div>'}`;
}
function duplicateDetail(id){
 const g=(data.duplicate_groups||[]).find(x=>x.id===id);if(!g)return;
 modal(`${esc(g.name)} · 重复来源对照`,`${esc(g.student_id)} · ${g.count} 条申报 · ${g.file_count} 个来源文件`,`<div class="dialog-body"><h3>${esc(g.event)}</h3><p class="help-text">${esc(g.category)} · 下方同时显示保留项和所有不重复计入项，可直接核对出处。</p>${duplicateComparison(g)}<div class="notice">本组关系：${esc(g.match_type||'完全重复')}。完全重复按关键申报字段一致识别；同项目按学生、类别和项目归并名关联，时间、级别或奖项可以不同。若实际上是分别发生的活动，请审核并补充不同的项目名称或归并名称。</div></div>`,'',true);
}
function duplicatesPage(){
 const all=data.duplicate_groups||[],q=filter.q.toLowerCase();
 const groups=all.filter(g=>(duplicateScope==='all'||(duplicateScope==='done'?g.resolved:!g.resolved))&&(g.name+g.student_id+g.event+g.member_ids.map(id=>{const r=data.records.find(r=>r.id===id);return r?r.source+r.sheet:''}).join(' ')).toLowerCase().includes(q)&&(!filter.category||g.category===filter.category));
 const pager=pagination(groups.length);
 return heading('重复与同项目核对','对照所有来源，同时查看保留项、完全重复项和同项目不叠加项。',exportLink('duplicates','↓ 导出重复对照'))+`<div class="review-banner"><div><strong>${num(all.length)} 个来源对照组 · ${num(all.reduce((n,g)=>n+g.count,0))} 条关联申报</strong><p>可核算记录按规则保留一条，其余不叠加；待审核项仍待确认。完全重复与同项目取最高分别标明。</p></div></div><section class="panel"><div class="toolbar"><div class="actions">${button('待处理','duplicate-scope',duplicateScope!=='open',false,'data-scope="open"')}${button('已处理','duplicate-scope',duplicateScope!=='done',false,'data-scope="done"')}${button('全部','duplicate-scope',duplicateScope!=='all',false,'data-scope="all"')}</div></div>${filtersHTML('review')}<div class="table-summary">可搜索姓名、学号、活动或来源文件。绿色底色标记保留项。</div></section><div class="duplicate-groups">${groups.slice((pageNo-1)*40,pageNo*40).map(g=>`<section class="panel duplicate-group"><div class="panel-head"><div><h2>${esc(g.name)} <small>${esc(g.student_id)}</small></h2><p>${esc(g.event)}</p></div><span class="tag duplicate">${g.resolved?'已处理 · ':''}${esc(g.match_type||'完全重复')} · ${g.count} 条 / ${g.file_count} 个文件</span></div>${duplicateComparison(g)}</section>`).join('')}</div>${!groups.length?`<section class="panel">${empty('没有匹配的重复组','同一申报在多个来源出现时，会将保留项和重复项一起列在这里。')}</section>`:''}<section class="panel">${pager}</section>`;
}
